<?php require 'bootstrap.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();q('UPDATE users SET active=? WHERE id=? AND role="customer"',[post('active')==='1'?1:0,(int)post('id')]);flash('อัปเดตสถานะสมาชิกแล้ว');go('admin/users.php');}admin_header('สมาชิก');?><form class="filters"><input name="q" placeholder="ชื่อหรืออีเมล" value="<?=e($_GET['q']??'')?>"><button><?=e(t('ค้นหา'))?></button></form><div class="table-wrap"><table><tr><th>ชื่อ</th><th><?=e(t('อีเมล'))?></th><th>วันที่สมัคร</th><th><?=e(t('คำสั่งซื้อ'))?></th><th>บัญชี</th></tr><?php $search='%'.($_GET['q']??'').'%';foreach(q('SELECT u.id,u.name,u.email,u.created_at,u.active,u.role,COUNT(o.id) order_count FROM users u LEFT JOIN orders o ON u.id=o.user_id WHERE u.name LIKE ? OR u.email LIKE ? GROUP BY u.id ORDER BY u.id DESC',[$search,$search]) as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['created_at'])?></td><td><a href="users.php?user=<?=$u['id']?>"><?=$u['order_count']?> <?=e(t('รายการ'))?></a></td><td><?php if($u['role']==='customer'):?><form method="post"><?=csrf()?><input type="hidden" name="id" value="<?=$u['id']?>"><button name="active" value="<?=$u['active']?0:1?>"><?=$u['active']?'ระงับ':'เปิดใช้งาน'?></button></form><?php else:?>Admin<?php endif ?></td></tr><?php endforeach ?></table></div><?php if(isset($_GET['user'])):?><h2>ประวัติคำสั่งซื้อสำหรับบริการลูกค้า</h2><?php foreach(q('SELECT id,total,status FROM orders WHERE user_id=? ORDER BY id DESC',[(int)$_GET['user']]) as $o):?><p><a href="order_detail.php?id=<?=$o['id']?>">BP-<?=$o['id']?></a> · <?=money($o['total'])?> · <?=STATUSES[$o['status']]?></p><?php endforeach;endif;admin_footer();?>
